// navigation contexts stay in memory (MDA contexts carry presenter objects history state cannot hold)
const contexts = {};
function FormRoute() {
  const { form } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  app.navigate = (formId, context) => { app.previous = app.current; contexts[formId] = context; navigate("/" + formId); };
  if (!app.forms[form]) return <Navigate to="/Form1" replace />;
  app.current = form;
  return <FormHost formId={form} context={contexts[form]} navKey={location.key} View={VIEWS[form]} />;
}

createRoot(document.getElementById("root")).render(
  <HashRouter>
    <Routes>
      <Route path="/:form" element={<FormRoute />} />
      <Route path="*" element={<Navigate to="/Form1" replace />} />
    </Routes>
  </HashRouter>
);
